using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;
// Review-only material/vegetation pass. Cars/source maps and fight floor height remain unchanged.
public static class ComponentCourtyardSurfaceReview {
 const string Dir="Assets/LighFight/Art/Drafts/ComponentCourtyardReview";
 static Material Material(string name,Shader shader,Color color){string path=Dir+"/"+name+".mat";var m=AssetDatabase.LoadAssetAtPath<Material>(path);if(!m){m=new Material(shader);AssetDatabase.CreateAsset(m,path);}m.shader=shader;m.color=color;EditorUtility.SetDirty(m);return m;}
 public static void Apply(){var shader=AssetDatabase.LoadAssetAtPath<Shader>(Dir+"/CourtyardWeathered.shader");if(!shader)throw new Exception("Weathered review shader required");var gravel=Material("GravelWorldReview",shader,Color.white);gravel.SetFloat("_Wall",0);string groundPath=Dir+"/Textures/gravel-albedo-v1.png";var groundImporter=(TextureImporter)AssetImporter.GetAtPath(groundPath);if(groundImporter==null)throw new Exception("Generated source ground texture missing");groundImporter.sRGBTexture=true;groundImporter.npotScale=TextureImporterNPOTScale.None;groundImporter.maxTextureSize=8192;groundImporter.wrapMode=TextureWrapMode.Repeat;groundImporter.filterMode=FilterMode.Trilinear;groundImporter.anisoLevel=8;groundImporter.mipmapEnabled=true;groundImporter.textureCompression=TextureImporterCompression.Uncompressed;groundImporter.SaveAndReimport();gravel.SetTexture("_GroundTex",AssetDatabase.LoadAssetAtPath<Texture2D>(groundPath));var wall=Material("WallWorldReview",shader,Color.white);wall.SetFloat("_Wall",1);var leaf=Material("LeafGeometryReview",Shader.Find("Standard"),new Color(.30f,.40f,.11f));leaf.SetFloat("_Glossiness",.16f);var bark=Material("BranchGeometryReview",Shader.Find("Standard"),new Color(.24f,.20f,.15f));string path=Dir+"/arena-component-review.prefab";var root=PrefabUtility.LoadPrefabContents(path);try{foreach(var r in root.GetComponentsInChildren<Renderer>()){if(r.name=="FightFloor")r.sharedMaterial=gravel;if(r.name=="Right outbuilding wall"||r.name=="Left boundary")r.sharedMaterial=wall;}foreach(var t in root.GetComponentsInChildren<Transform>().Where(t=>t.name.StartsWith("Separate foliage cluster")||t.name.StartsWith("Separate tree trunk")).ToArray())UnityEngine.Object.DestroyImmediate(t.gameObject);
 if(!root.transform.Find("Rear low boundary")){var fence=GameObject.CreatePrimitive(PrimitiveType.Cube);fence.name="Rear low boundary";fence.transform.SetParent(root.transform,false);fence.transform.localPosition=new Vector3(0,.625f,7.3f);fence.transform.localScale=new Vector3(14,1.25f,.16f);fence.GetComponent<Renderer>().sharedMaterial=wall;UnityEngine.Object.DestroyImmediate(fence.GetComponent<Collider>());}var vertices=new List<Vector3>();var indices=new List<int>();var random=new System.Random(505);
 for(int tree=0;tree<9;tree++){float x=tree<2?-10:tree<4?8:(tree-6)*3f,z=tree<4?4+tree*.65f:9f;Branch(root.transform,new Vector3(x,0,z),new Vector3(x+.18f,4.5f,z+.12f),.17f,bark);for(int branch=0;branch<9;branch++){float angle=branch*2.39996f;var start=new Vector3(x,2.6f+branch*.12f,z);var end=start+new Vector3(Mathf.Cos(angle)*1.05f,.75f,Mathf.Sin(angle)*.9f);Branch(root.transform,start,end,.035f,bark);}for(int n=0;n<1000;n++){float a=(float)random.NextDouble()*Mathf.PI*2,rad=Mathf.Sqrt((float)random.NextDouble())*1.35f;var center=new Vector3(x+Mathf.Cos(a)*rad,3.4f+(float)random.NextDouble()*1.6f,z+Mathf.Sin(a)*rad);var rotation=Quaternion.Euler((float)random.NextDouble()*130, (float)random.NextDouble()*360,(float)random.NextDouble()*80);float size=.045f+(float)random.NextDouble()*.055f;int first=vertices.Count;var leafVertices=new[]{new Vector3(0,0,-1),new Vector3(-.42f,0,0),new Vector3(0,.15f,0),new Vector3(.42f,0,0),new Vector3(0,0,1)};foreach(var v in leafVertices)vertices.Add(center+rotation*v*size);foreach(var v in leafVertices)vertices.Add(center+rotation*v*size);indices.AddRange(new[]{first,first+1,first+2,first,first+2,first+3,first+1,first+4,first+2,first+2,first+4,first+3,first+7,first+6,first+5,first+8,first+7,first+5,first+7,first+9,first+6,first+8,first+9,first+7});}}
 var mesh=new Mesh{name="9000 folded double-sided 3D leaves",indexFormat=UnityEngine.Rendering.IndexFormat.UInt32};mesh.SetVertices(vertices);mesh.SetTriangles(indices,0);mesh.RecalculateNormals();mesh.RecalculateBounds();string mp=Dir+"/review-leaves.mesh.asset";var old=AssetDatabase.LoadAssetAtPath<Mesh>(mp);if(old){EditorUtility.CopySerialized(mesh,old);UnityEngine.Object.DestroyImmediate(mesh);mesh=old;}else AssetDatabase.CreateAsset(mesh,mp);var go=new GameObject("Thin separate leaf surface");go.transform.SetParent(root.transform,false);go.AddComponent<MeshFilter>().sharedMesh=mesh;go.AddComponent<MeshRenderer>().sharedMaterial=leaf;PrefabUtility.SaveAsPrefabAsset(root,path);AssetDatabase.SaveAssets();}finally{PrefabUtility.UnloadPrefabContents(root);}Debug.Log("AGENT_RESULT generated gravel albedo/procedural wall + 9000 folded leaves review applied; no source/car/UV changes; unaccepted");}
 static void Branch(Transform root,Vector3 a,Vector3 b,float radius,Material mat){var go=GameObject.CreatePrimitive(PrimitiveType.Cylinder);go.name="Review branch";go.transform.SetParent(root,false);go.transform.position=(a+b)*.5f;go.transform.up=(b-a).normalized;go.transform.localScale=new Vector3(radius,(b-a).magnitude*.5f,radius);go.GetComponent<Renderer>().sharedMaterial=mat;UnityEngine.Object.DestroyImmediate(go.GetComponent<Collider>());}
}
